{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.product_journey as ( with price as ( SELECT upper(trim(LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))))) AS sku_group, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku_group)) as sku_group, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price ), final_price_adj as ( select sku_group, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), final_price as ( select sku_group, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), live_date AS ( SELECT min(published_at::date) AS live_date, upper(trim(LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))))) AS sku_group, FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT where published_at::date is not null group by 2 ), first_order_date as ( select upper(trim(sku_group)) as sku_group, min(date) as live_date2 from snitch_db.maplemonk.horizontal_sales_categories group by 1 ), final_live_date as ( select coalesce(upper(trim(a.sku_group)),b.sku_group) as sku_group, case when a.live_date <= b.live_date2 then a.live_date else b.live_date2 end as final_live_date from live_date a full outer join first_order_date b on upper(trim(a.sku_group)) = b.sku_group ), sales_data as ( select UPPER(TRIM(a.sku_group)) AS sku_group, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as store_quant7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as shopify_quant7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as marketplace_quant7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as store_quant30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as shopify_quant30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as marketplace_quant30, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as store_sales7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as shopify_sales7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as marketplace_sales7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as store_sales30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as shopify_sales30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as marketplace_sales30, ifnull(sum(case when type = \'Store\' then gross_sales end),0) as store_sales, ifnull(sum(case when type = \'Shopify\' then gross_sales end),0) as shopify_sales, ifnull(sum(case when type = \'Marketplace\' then gross_sales end),0) as marketplace_sales, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as store_discount7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as shopify_discount7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as marketplace_discount7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as store_discount30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as shopify_discount30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as marketplace_discount30, ifnull(sum(case when type = \'Store\' then discount_amount end),0) as store_discount, ifnull(sum(case when type = \'Shopify\' then discount_amount end),0) as shopify_discount, ifnull(sum(case when type = \'Marketplace\' then discount_amount end),0) as marketplace_discount, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.live_date,date) <=31 then gross_quantity end),0) as marketplace_quant_first30, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.live_date,date) <=31 then gross_quantity end),0) as shopify_quant_first30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.live_date,date) <=61 then gross_quantity end),0) as marketplace_quant_first60, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.live_date,date) <=61 then gross_quantity end),0) as shopify_quant_first60 from snitch_db.maplemonk.horizontal_sales_categories a left join snitch_db.maplemonk.availability_master_v2 b on upper(trim(a.sku_group)) = upper(trim(b.sku_group)) group by 1 ), aging as ( select upper(trim(SKU_GROUP)) as sku_group, ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'0-30\') then units_on_hand end),0) as \"inv<30\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'60-90\',\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>60\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>90\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>120\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>180\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>240\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>300\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'>360\') then units_on_hand end),0) as \"inv>360\", ifnull(sum(units_on_hand),0) as units_on_hand, round(sum(\"Days in warehouse\"*units_on_hand)/sum(units_on_hand),0) as overall_aging from snitch_db.maplemonk.overall_aging group by 1 ), clicks as ( select upper(trim(sku_group)) as sku_group, sum(case when datediff(day,ga_date,current_date) <=8 then clicks end) clicks_7, sum(case when datediff(day,ga_date,current_date) <=31 then clicks end) clicks_30 from snitch_db.maplemonk.clicks_itemid group by 1 ), inv as ( select upper(trim(sku_group)) as sku_group, sellable_inventory, category, live_date from snitch_db.maplemonk.availability_master_v2 where status != \'draft\' ), offline_inventory as ( SELECT upper(trim(sku_group)) as sku_group, sum(inventory+JIT_QTY) as offline_inventory, FROM snitch_db.maplemonk.offline_master group by 1 ), design as ( select upper(trim(sku_group)) as sku_group, case when div0(FIRST_30D_SALES,INVENTORY) < 0.3 and HIT_SIZES < 3 then \'hit\' else \'non_hit\' end as strike, inventory as starting_inventory from snitch_db.maplemonk.design_fact_items ), inwards as ( select upper(trim(LEFT(\"Item Type skuCode\", LENGTH(\"Item Type skuCode\") - CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\"))))) AS sku_group, created::date as inward_date, sum(\"Total Quantity\") as inward_quantity from snitch_db.maplemonk.snitch_final_get_put_away_new where type = \'PUTAWAY_GRN_ITEM\' group by 1,2 having sum(\"Total Quantity\") > 30 ), inwards_data as ( select upper(trim(sku_group)) as sku_group, count(distinct date_trunc(month,inward_date)) as inward_count, max(inward_date) as last_inward, datediff(day,max(inward_date),current_date) as days_since_inward from inwards group by 1 ), returns as ( select upper(trim(sku_group)) as sku_group, round(sum(case when datediff(day,order_date,current_date) <=31 then return_qty end),0) shopify_return_30, round(sum(case when datediff(day,order_date,current_date) <=8 then return_qty end),0) shopify_return_7, from snitch_db.maplemonk.return_fact_items group by 1 ), cost_price as ( select upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) AS sku_group, max(cost_price) as cost_price from snitch_db.maplemonk.sku_cost_price group by 1 ), main_data AS ( SELECT a.sku_group, a.category, a.sellable_inventory AS current_inventory, o.offline_inventory, DATEDIFF(DAY, e.final_live_date, CURRENT_DATE) AS days_live, b.original_price, c.\"inv<30\", c.\"inv>60\", c.\"inv>90\", c.\"inv>120\", c.\"inv>180\", c.\"inv>240\", c.\"inv>300\", c.\"inv>360\", c.overall_aging, c.units_on_hand, IFNULL(d.store_quant7, 0) AS store_quant7, IFNULL(d.shopify_quant7, 0) AS shopify_quant7, IFNULL(d.marketplace_quant7, 0) AS marketplace_quant7, IFNULL(d.store_quant30, 0) AS store_quant30, IFNULL(d.shopify_quant30, 0) AS shopify_quant30, IFNULL(d.marketplace_quant30, 0) AS marketplace_quant30, IFNULL(d.store_sales7, 0) AS store_sales7, IFNULL(d.shopify_sales7, 0) AS shopify_sales7, IFNULL(d.marketplace_sales7, 0) AS marketplace_sales7, IFNULL(d.store_sales30, 0) AS store_sales30, IFNULL(d.shopify_sales30, 0) AS shopify_sales30, IFNULL(d.marketplace_sales30, 0) AS marketplace_sales30, IFNULL(d.store_sales, 0) AS store_sales, IFNULL(d.shopify_sales, 0) AS shopify_sales, IFNULL(d.marketplace_sales, 0) AS marketplace_sales, IFNULL(d.store_discount7, 0) AS store_discount7, IFNULL(d.shopify_discount7, 0) AS shopify_discount7, IFNULL(d.marketplace_discount7, 0) AS marketplace_discount7, IFNULL(d.store_discount30, 0) AS store_discount30, IFNULL(d.shopify_discount30, 0) AS shopify_discount30, IFNULL(d.marketplace_discount30, 0) AS marketplace_discount30, IFNULL(d.store_discount, 0) AS store_discount, IFNULL(d.shopify_discount, 0) AS shopify_discount, IFNULL(d.marketplace_discount, 0) AS marketplace_discount, IFNULL(f.clicks_30, 0) AS clicks_30, IFNULL(f.clicks_7, 0) AS clicks_7, g.strike, e.final_live_date, IFNULL(h.inward_count, 0) AS inward_count, h.last_inward, h.days_since_inward, i.shopify_return_30, i.shopify_return_7, p.cost_price FROM inv a LEFT JOIN final_price b ON a.sku_group = b.sku_group LEFT JOIN aging c ON a.sku_group = c.sku_group LEFT JOIN sales_data d ON a.sku_group = d.sku_group LEFT JOIN final_live_date e ON a.sku_group = e.sku_group LEFT JOIN clicks f ON a.sku_group = f.sku_group LEFT JOIN design g ON a.sku_group = g.sku_group LEFT JOIN inwards_data h ON a.sku_group = h.sku_group LEFT JOIN returns i ON a.sku_group = i.sku_group left join offline_inventory o on a.sku_group = o.sku_group left join cost_price p on a.sku_group = p.sku_group WHERE a.sellable_inventory IS NOT NULL AND a.sellable_inventory != 0 ) SELECT sku_group, category, current_inventory AS inventory, offline_inventory, original_price, cost_price, inward_count, days_since_inward, last_inward, DATEDIFF(DAY, final_live_date, CURRENT_DATE) AS days_since_live, CASE WHEN units_on_hand <> 0 THEN \"inv>60\" / units_on_hand ELSE 0 END AS inv_60, CASE WHEN units_on_hand <> 0 THEN \"inv>90\" / units_on_hand ELSE 0 END AS inv_90, CASE WHEN units_on_hand <> 0 THEN \"inv>120\" / units_on_hand ELSE 0 END AS inv_120, CASE WHEN units_on_hand <> 0 THEN \"inv>180\" / units_on_hand ELSE 0 END AS inv_180, CASE WHEN units_on_hand <> 0 THEN \"inv>240\" / units_on_hand ELSE 0 END AS inv_240, CASE WHEN units_on_hand <> 0 THEN \"inv>300\" / units_on_hand ELSE 0 END AS inv_300, CASE WHEN units_on_hand <> 0 THEN \"inv>360\" / units_on_hand ELSE 0 END AS inv_360, overall_aging, shopify_return_7, shopify_return_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN store_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS store_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN shopify_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS shopify_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN (shopify_quant7 - shopify_return_7) / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS net_shopify_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN marketplace_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS marketplace_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN store_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS store_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN shopify_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS shopify_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN (shopify_quant30 - shopify_return_30) / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS net_shopify_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN marketplace_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS marketplace_ros_30, CASE WHEN (store_discount7 + store_sales7) <> 0 THEN (store_discount7 / (store_discount7 + store_sales7)) * 100 ELSE 0 END AS store_discount_7_percentage, CASE WHEN (store_discount30 + store_sales30) <> 0 THEN (store_discount30 / (store_discount30 + store_sales30)) * 100 ELSE 0 END AS store_discount_30_percentage, CASE WHEN (shopify_discount7 + shopify_sales7) <> 0 THEN (shopify_discount7 / (shopify_discount7 + shopify_sales7)) * 100 ELSE 0 END AS shopify_discount_7_percentage, CASE WHEN (shopify_discount30 + shopify_sales30) <> 0 THEN (shopify_discount30 / (shopify_discount30 + shopify_sales30)) * 100 ELSE 0 END AS shopify_discount_30_percentage, CASE WHEN (marketplace_discount7 + marketplace_sales7) <> 0 THEN (marketplace_discount7 / (marketplace_discount7 + marketplace_sales7)) * 100 ELSE 0 END AS marketplace_discount_7_percentage, CASE WHEN (marketplace_discount30 + marketplace_sales30) <> 0 THEN (marketplace_discount30 / (marketplace_discount30 + marketplace_sales30)) * 100 ELSE 0 END AS marketplace_discount_30_percentage, CASE WHEN (store_discount + store_sales) <> 0 THEN (store_discount / (store_discount + store_sales)) * 100 ELSE 0 END AS store_discount_percentage, CASE WHEN (shopify_discount + shopify_sales) <> 0 THEN (shopify_discount / (shopify_discount + shopify_sales)) * 100 ELSE 0 END AS shopify_discount_percentage, CASE WHEN (marketplace_discount + marketplace_sales) <> 0 THEN (marketplace_discount / (marketplace_discount + marketplace_sales)) * 100 ELSE 0 END AS marketplace_discount_percentage, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN clicks_30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS clicks_rate_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN clicks_7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS clicks_rate_7, strike FROM main_data ); create or replace table snitch_db.maplemonk.aging_shopify_inventory_value as ( select sku_group, category, case when overall_aging is not null then overall_aging when overall_aging is null and days_since_inward is not null and days_since_inward <= days_since_live then days_since_inward when overall_aging is null and days_since_inward is not null and days_since_inward > days_since_live then days_since_live when days_since_inward is null then days_since_live end as overall_aging, cost_price, sum(inventory) as inventory from snitch_db.maplemonk.product_journey where sku_group not in (\'4MSS3481-04\',\'4MSS3481-03\',\'4MSS3481-06\',\'4MSS3481-05\',\'4MSS3481-07\',\'4MSS3481-01\',\'4MSS3481-02\') group by 1,2,3,4 );",
